param(
    [string]$Session = "cot-drift-probe",
    [string]$Job = "run_experiment.py",
    [string]$RemoteResult = "/content/cot_drift_results.json",
    [string]$LocalResult = "artifacts/cot_drift_results.json"
)

$ErrorActionPreference = "Stop"
$workspace = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path
$stage = Join-Path $env:TEMP "cot-drift-upload"
$localResultPath = Join-Path $workspace $LocalResult
$localResultDirectory = Split-Path $localResultPath -Parent

New-Item -ItemType Directory -Path $stage -Force | Out-Null
New-Item -ItemType Directory -Path $localResultDirectory -Force | Out-Null

$files = @(
    "cot_drift.py",
    "run_experiment.py",
    "requirements-colab.txt",
    $Job
) | Select-Object -Unique

foreach ($file in $files) {
    $source = Join-Path $workspace $file
    if (-not (Test-Path -LiteralPath $source)) {
        throw "Required file not found: $source"
    }
    Copy-Item -LiteralPath $source -Destination $stage -Force
}

$wslStage = (& wsl.exe --cd /home/finn wslpath -a ($stage -replace "\\", "/")).Trim()
$stagedResult = Join-Path $stage ([IO.Path]::GetFileName($RemoteResult))
$wslStagedResult = (& wsl.exe --cd /home/finn wslpath -a ($stagedResult -replace "\\", "/")).Trim()
$sessionCreated = $false

try {
    & wsl.exe --cd /home/finn colab new -s $Session --gpu T4
    if ($LASTEXITCODE -ne 0) { throw "Failed to allocate Colab session" }
    $sessionCreated = $true

    foreach ($file in $files) {
        & wsl.exe --cd /home/finn colab upload -s $Session "$wslStage/$file" "/content/$file"
        if ($LASTEXITCODE -ne 0) { throw "Failed to upload $file" }
    }

    & wsl.exe --cd /home/finn colab install -s $Session -r "$wslStage/requirements-colab.txt"
    if ($LASTEXITCODE -ne 0) { throw "Failed to install Colab requirements" }

    & wsl.exe --cd /home/finn colab exec -s $Session -f "$wslStage/$Job" --timeout 1800
    if ($LASTEXITCODE -ne 0) { throw "Colab job failed" }

    & wsl.exe --cd /home/finn colab download -s $Session $RemoteResult $wslStagedResult
    if ($LASTEXITCODE -ne 0) { throw "Failed to download result artifact" }
    Copy-Item -LiteralPath $stagedResult -Destination $localResultPath -Force
    Write-Host "Saved result to $localResultPath"
}
finally {
    if ($sessionCreated) {
        & wsl.exe --cd /home/finn colab stop -s $Session
    }
}

