def repeat_cache(cache: Any, repeats: int) -> Any:
    """Copy one prefix cache and repeat its batch dimension for a population."""

    if repeats < 1:
        raise ValueError("Cache repeat count must be positive")
    expanded = clone_cache(cache)
    if repeats == 1:
        return expanded
    if hasattr(expanded, "batch_repeat_interleave"):
