    if missing:
        update_run(run_dir, state="outputs_missing", missing_outputs=missing)
        raise BatchError(f"Expected Kaggle outputs are missing: {missing}")
    files = [
        {
            "path": path.relative_to(output_dir).as_posix(),
            "bytes": path.stat().st_size,
            "sha256": sha256(path),
        }
        for path in sorted(output_dir.rglob("*"))
        if path.is_file()
    ]
    update_run(run_dir, state="retrieved", retrieved_utc=utc_now(), output_files=files)


def write_remote_logs(run_dir: Path, follow: bool) -> int:
    identifier = kernel_id(read_run(run_dir))
    arguments = ["kernels", "logs"]
    if follow:
        arguments.append("-f")
    arguments.append(identifier)
    if follow:
        return subprocess.call([kaggle_executable(), *arguments])
    result = kaggle(arguments)
    (run_dir / "remote.log").write_text(result.stdout, encoding="utf-8")
