#!/usr/bin/env python3
"""Safe wrapper around the official asynchronous Kaggle Kernel CLI."""

from __future__ import annotations

import argparse
import datetime as dt
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import time
from pathlib import Path, PurePosixPath
from typing import Any, Sequence


TOOL_VERSION = "1.0.0"
TERMINAL_SUCCESS = ("complete", "success")
TERMINAL_FAILURE = ("error", "fail", "cancel")
SENSITIVE_PARTS = {
    ".env",
    ".git",
    ".kaggle",
    "access_token",
    "kaggle.json",
    "credentials",
    "credential",
    "secret",
    "secrets",
    "private_key",
    "id_rsa",
}


class BatchError(RuntimeError):
    pass


def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).replace(microsecond=0).isoformat()


def compact_stamp() -> str:
    return dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def json_write(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2) + "\n", encoding="utf-8")


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def run_process(arguments: Sequence[str], cwd: Path | None = None) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        list(arguments),
        cwd=str(cwd) if cwd else None,
        text=True,
        encoding="utf-8",
        errors="replace",
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
    )


def kaggle_executable() -> str:
    executable = shutil.which("kaggle")
    if not executable:
        raise BatchError("Official Kaggle CLI not found on PATH; install the `kaggle` package")
    return executable


def kaggle(arguments: Sequence[str]) -> subprocess.CompletedProcess[str]:
    return run_process([kaggle_executable(), *arguments])


def safe_relative_path(value: str, label: str) -> PurePosixPath:
    normalized = value.replace("\\", "/")
    path = PurePosixPath(normalized)
    if path.is_absolute() or not path.parts or any(part in {"", ".", ".."} for part in path.parts):
        raise BatchError(f"{label} must be a traversal-free relative path: {value!r}")
    lowered = {part.lower() for part in path.parts}
    if lowered & SENSITIVE_PARTS or any(part.endswith((".pem", ".key")) for part in lowered):
        raise BatchError(f"{label} resembles sensitive material and cannot be packaged: {value!r}")
    return path


def load_spec(project: Path, spec_path: Path, allow_public: bool = False) -> dict[str, Any]:
    try:
        spec = json.loads(spec_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        raise BatchError(f"Cannot read job spec {spec_path}: {error}") from error

    if spec.get("schema_version") != 1:
        raise BatchError("Job spec schema_version must be 1")
    kernel = spec.get("kernel")
    if not isinstance(kernel, dict):
        raise BatchError("Job spec requires a kernel object")
    kernel_id = kernel.get("id", "")
    if not re.fullmatch(r"[A-Za-z0-9_-]+/[a-z0-9][a-z0-9-]*", kernel_id):
        raise BatchError("kernel.id must have Kaggle owner/lowercase-slug form")
    if not isinstance(kernel.get("title"), str) or not kernel["title"].strip():
        raise BatchError("kernel.title must be a nonempty string")
    kernel_type = kernel.get("kernel_type")
    if kernel_type not in {"script", "notebook"}:
        raise BatchError("kernel.kernel_type must be script or notebook")
    code_file = safe_relative_path(str(kernel.get("code_file", "")), "kernel.code_file")
    expected_suffix = ".py" if kernel_type == "script" else ".ipynb"
    if code_file.suffix.lower() != expected_suffix:
        raise BatchError(f"{kernel_type} code_file must end in {expected_suffix}")
    is_private = kernel.get("is_private", True)
    if not isinstance(is_private, bool):
        raise BatchError("kernel.is_private must be boolean")
    if not is_private and not allow_public:
        raise BatchError("Public kernel packaging requires explicit --allow-public")
    if not isinstance(kernel.get("enable_internet", False), bool):
        raise BatchError("kernel.enable_internet must be boolean")

    accelerator = spec.get("accelerator")
    if accelerator is not None and (not isinstance(accelerator, str) or not accelerator.strip()):
        raise BatchError("accelerator must be a nonempty string or null")
    timeout_seconds = spec.get("timeout_seconds", 3600)
    if not isinstance(timeout_seconds, int) or not 60 <= timeout_seconds <= 43200:
        raise BatchError("timeout_seconds must be an integer from 60 through 43200")

    files = spec.get("files")
    if not isinstance(files, list) or not files:
        raise BatchError("files must be a nonempty allowlist")
    normalized_files: list[dict[str, str]] = []
    destinations: set[str] = set()
    project_resolved = project.resolve()
    for entry in files:
        if isinstance(entry, str):
            source_value = entry
            destination_value = entry
        elif isinstance(entry, dict):
            source_value = entry.get("source", "")
            destination_value = entry.get("destination", source_value)
        else:
            raise BatchError("Each files entry must be a string or source/destination object")
        source_rel = safe_relative_path(str(source_value), "files.source")
        destination_rel = safe_relative_path(str(destination_value), "files.destination")
        source = (project_resolved / Path(*source_rel.parts)).resolve()
        try:
            source.relative_to(project_resolved)
        except ValueError as error:
            raise BatchError(f"Source escapes project root: {source_value}") from error
        if not source.is_file():
            raise BatchError(f"Source is not a file: {source}")
        destination = destination_rel.as_posix()
        if destination in destinations:
            raise BatchError(f"Duplicate packaged destination: {destination}")
        destinations.add(destination)
        normalized_files.append({"source": str(source), "destination": destination})
    if code_file.as_posix() not in destinations:
        raise BatchError("kernel.code_file must be one of the packaged destinations")

    for source_key in ("dataset_sources", "kernel_sources", "model_sources"):
        values = spec.get(source_key, [])
        if not isinstance(values, list) or not all(isinstance(value, str) for value in values):
            raise BatchError(f"{source_key} must be an array of strings")
    outputs = spec.get("expected_outputs", [])
    if not isinstance(outputs, list) or not all(isinstance(value, str) for value in outputs):
        raise BatchError("expected_outputs must be an array of strings")
    for output in outputs:
        safe_relative_path(output, "expected_outputs")

    validated = dict(spec)
    validated["files"] = normalized_files
    validated["timeout_seconds"] = timeout_seconds
    validated["expected_outputs"] = outputs
    validated["accelerator"] = accelerator
    return validated


def git_snapshot(project: Path) -> dict[str, Any]:
    commit = run_process(["git", "rev-parse", "HEAD"], cwd=project)
    status = run_process(["git", "status", "--porcelain"], cwd=project)
    return {
        "commit": commit.stdout.strip() if commit.returncode == 0 else None,
        "dirty": bool(status.stdout.strip()) if status.returncode == 0 else None,
    }


def metadata_for(spec: dict[str, Any]) -> dict[str, Any]:
    kernel = spec["kernel"]
    accelerator = (spec.get("accelerator") or "").lower()
    return {
        "id": kernel["id"],
        "title": kernel["title"],
        "code_file": PurePosixPath(kernel["code_file"]).as_posix(),
        "language": "python",
        "kernel_type": kernel["kernel_type"],
        "is_private": kernel.get("is_private", True),
        "enable_gpu": accelerator.startswith("nvidia"),
        "enable_tpu": accelerator.startswith("tpu"),
        "enable_internet": kernel.get("enable_internet", False),
        "dataset_sources": spec.get("dataset_sources", []),
        "kernel_sources": spec.get("kernel_sources", []),
        "model_sources": spec.get("model_sources", []),
    }


def create_run(project: Path, spec_path: Path, runs_dir: Path, allow_public: bool) -> Path:
    spec = load_spec(project, spec_path, allow_public=allow_public)
    slug = spec["kernel"]["id"].split("/", 1)[1]
    run_dir = (runs_dir / slug / compact_stamp()).resolve()
    if run_dir.exists():
        raise BatchError(f"Refusing to overwrite existing run directory: {run_dir}")
    bundle = run_dir / "bundle"
    bundle.mkdir(parents=True)

    packaged: list[dict[str, Any]] = []
    for entry in spec["files"]:
        source = Path(entry["source"])
        destination = bundle / Path(*PurePosixPath(entry["destination"]).parts)
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, destination)
        packaged.append(
            {
                "source": str(source),
                "destination": entry["destination"],
                "bytes": destination.stat().st_size,
                "sha256": sha256(destination),
            }
        )

    json_write(bundle / "kernel-metadata.json", metadata_for(spec))
    manifest = {
        "tool": "kaggle-batch",
        "tool_version": TOOL_VERSION,
        "created_utc": utc_now(),
        "project": str(project.resolve()),
        "spec_path": str(spec_path.resolve()),
        "git": git_snapshot(project),
        "job": spec,
        "packaged_files": packaged,
    }
    json_write(bundle / "run_manifest.json", manifest)
    json_write(run_dir / "local_run.json", {"state": "packaged", **manifest})
    return run_dir


def read_run(run_dir: Path) -> dict[str, Any]:
    path = run_dir / "local_run.json"
    if not path.is_file():
        raise BatchError(f"Not a Kaggle batch run directory: {run_dir}")
    return json.loads(path.read_text(encoding="utf-8"))


def update_run(run_dir: Path, **updates: Any) -> dict[str, Any]:
    record = read_run(run_dir)
    record.update(updates)
    json_write(run_dir / "local_run.json", record)
    return record


def submit_run(run_dir: Path) -> None:
    record = read_run(run_dir)
    job = record["job"]
    arguments = [
        "kernels",
        "push",
        "-p",
        str(run_dir / "bundle"),
        "-t",
        str(job["timeout_seconds"]),
    ]
    if job.get("accelerator"):
        arguments.extend(["--accelerator", job["accelerator"]])
    result = kaggle(arguments)
    (run_dir / "submit.log").write_text(result.stdout, encoding="utf-8")
    if result.returncode != 0:
        update_run(run_dir, state="submit_failed", submit_returncode=result.returncode)
        raise BatchError(f"Kaggle submission failed:\n{result.stdout}")
    update_run(run_dir, state="submitted", submitted_utc=utc_now())


def kernel_id(record: dict[str, Any]) -> str:
    return record["job"]["kernel"]["id"]


def query_status(identifier: str) -> tuple[str, subprocess.CompletedProcess[str]]:
    result = kaggle(["kernels", "status", identifier])
    if result.returncode != 0:
        return "api_error", result
    lowered = result.stdout.lower()
    if any(token in lowered for token in TERMINAL_FAILURE):
        return "failed", result
    if any(token in lowered for token in TERMINAL_SUCCESS):
        return "complete", result
    if any(token in lowered for token in ("run", "queue", "pending")):
        return "active", result
    return "unknown", result


def wait_for_run(run_dir: Path, poll_seconds: int, timeout_seconds: int) -> None:
    record = read_run(run_dir)
    identifier = kernel_id(record)
    deadline = time.monotonic() + timeout_seconds
    status_log = run_dir / "status.log"
    while True:
        state, result = query_status(identifier)
        with status_log.open("a", encoding="utf-8") as stream:
            stream.write(f"[{utc_now()}] state={state} returncode={result.returncode}\n{result.stdout.rstrip()}\n")
        print(f"{utc_now()} {identifier}: {state}", flush=True)
        if state == "complete":
            update_run(run_dir, state="complete", completed_utc=utc_now())
            return
        if state in {"failed", "api_error"}:
            update_run(run_dir, state=state, ended_utc=utc_now())
            raise BatchError(f"Kaggle kernel ended in {state}; inspect {status_log} and remote logs")
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            update_run(run_dir, state="wait_timeout", ended_utc=utc_now())
            raise BatchError(f"Timed out waiting for {identifier}; remote job may still be active")
        time.sleep(min(poll_seconds, remaining))


