            raise BatchError(f"Kaggle kernel ended in {state}; inspect {status_log} and remote logs")
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            update_run(run_dir, state="wait_timeout", ended_utc=utc_now())
            raise BatchError(f"Timed out waiting for {identifier}; remote job may still be active")
        time.sleep(min(poll_seconds, remaining))


def fetch_outputs(run_dir: Path) -> None:
    record = read_run(run_dir)
    identifier = kernel_id(record)
    output_dir = run_dir / "outputs"
    output_dir.mkdir(parents=True, exist_ok=True)
    result = kaggle(["kernels", "output", identifier, "-p", str(output_dir), "-o"])
    (run_dir / "fetch.log").write_text(result.stdout, encoding="utf-8")
    if result.returncode != 0:
        raise BatchError(f"Kaggle output retrieval failed:\n{result.stdout}")
    missing = []
    for relative in record["job"].get("expected_outputs", []):
        path = output_dir / Path(*PurePosixPath(relative).parts)
        if not path.is_file():
            missing.append(relative)
    if missing:
        update_run(run_dir, state="outputs_missing", missing_outputs=missing)
        raise BatchError(f"Expected Kaggle outputs are missing: {missing}")
    files = [
        {
            "path": path.relative_to(output_dir).as_posix(),
            "bytes": path.stat().st_size,
            "sha256": sha256(path),
        }
        for path in sorted(output_dir.rglob("*"))
        if path.is_file()
    ]
    update_run(run_dir, state="retrieved", retrieved_utc=utc_now(), output_files=files)


def write_remote_logs(run_dir: Path, follow: bool) -> int:
    identifier = kernel_id(read_run(run_dir))
    arguments = ["kernels", "logs"]
    if follow:
        arguments.append("-f")
    arguments.append(identifier)
    if follow:
        return subprocess.call([kaggle_executable(), *arguments])
    result = kaggle(arguments)
    (run_dir / "remote.log").write_text(result.stdout, encoding="utf-8")
    print(result.stdout, end="")
    return result.returncode


def preflight(allow_unauthenticated: bool) -> None:
    version = kaggle(["--version"])
    quota = kaggle(["quota"])
    value = {
        "cli": version.stdout.strip(),
        "cli_ok": version.returncode == 0,
        "authenticated": quota.returncode == 0,
        "quota": quota.stdout.strip(),
    }
    print(json.dumps(value, indent=2))
    if version.returncode != 0 or (quota.returncode != 0 and not allow_unauthenticated):
        raise BatchError("Kaggle preflight failed; authenticate with `kaggle auth login`")


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)

    preflight_parser = commands.add_parser("preflight")
    preflight_parser.add_argument("--allow-unauthenticated", action="store_true")

    for name in ("validate", "package", "run"):
        child = commands.add_parser(name)
        child.add_argument("--project", type=Path, required=True)
        child.add_argument("--spec", type=Path, required=True)
        child.add_argument("--allow-public", action="store_true")
        if name in {"package", "run"}:
            child.add_argument("--runs-dir", type=Path)
        if name == "run":
            child.add_argument("--poll-seconds", type=int, default=15)
            child.add_argument("--wait-timeout-seconds", type=int, default=43200)

    for name in ("submit", "fetch"):
        child = commands.add_parser(name)
        child.add_argument("--run-dir", type=Path, required=True)

    wait_parser = commands.add_parser("wait")
    wait_parser.add_argument("--run-dir", type=Path, required=True)
    wait_parser.add_argument("--poll-seconds", type=int, default=15)
    wait_parser.add_argument("--timeout-seconds", type=int, default=43200)

    status_parser = commands.add_parser("status")
    status_parser.add_argument("--run-dir", type=Path, required=True)

    logs_parser = commands.add_parser("logs")
    logs_parser.add_argument("--run-dir", type=Path, required=True)
    logs_parser.add_argument("--follow", action="store_true")
    return parser


def packaged_run(args: argparse.Namespace) -> Path:
    project = args.project.resolve()
    spec = args.spec.resolve()
    runs_dir = args.runs_dir.resolve() if args.runs_dir else project / ".kaggle" / "runs"
    run_dir = create_run(project, spec, runs_dir, args.allow_public)
    print(f"RUN_DIR={run_dir}")
    return run_dir


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        if args.command == "preflight":
            preflight(args.allow_unauthenticated)
        elif args.command == "validate":
            spec = load_spec(args.project.resolve(), args.spec.resolve(), args.allow_public)
            print(json.dumps({"valid": True, "kernel": spec["kernel"]["id"]}, indent=2))
        elif args.command == "package":
            packaged_run(args)
        elif args.command == "submit":
            submit_run(args.run_dir.resolve())
        elif args.command == "status":
            record = read_run(args.run_dir.resolve())
            state, result = query_status(kernel_id(record))
            print(result.stdout, end="")
            print(f"PARSED_STATE={state}")
            return result.returncode
        elif args.command == "wait":
            wait_for_run(args.run_dir.resolve(), args.poll_seconds, args.timeout_seconds)
        elif args.command == "logs":
            return write_remote_logs(args.run_dir.resolve(), args.follow)
        elif args.command == "fetch":
            fetch_outputs(args.run_dir.resolve())
        elif args.command == "run":
            run_dir = packaged_run(args)
            submit_run(run_dir)
            wait_for_run(run_dir, args.poll_seconds, args.wait_timeout_seconds)
            fetch_outputs(run_dir)
            print(f"OUTPUT_DIR={run_dir / 'outputs'}")
        return 0
    except BatchError as error:
        print(f"ERROR: {error}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

