"""Coordinate a pinned, checkpointed, dual-T4 bounded-controller campaign."""

from __future__ import annotations

import json
import os
import platform
import subprocess
import sys
import time
import traceback
from pathlib import Path
from typing import Any


ROOT = Path(__file__).resolve().parent
WORKING = Path("/kaggle/working") if Path("/kaggle/working").is_dir() else ROOT / ".kaggle-working"
CONFIG_PATH = ROOT / "bounded_campaign_config.json"
PROBLEMS_PATH = WORKING / "campaign_problems.json"
RESULT_PATH = WORKING / "cot_drift_t4x2_campaign.json"
STATUS_PATH = WORKING / "campaign_status.json"
FAMILIES = ("e1_e2_h", "e1_e2_e3_h")


def atomic_json_write(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, indent=2) + "\n", encoding="utf-8")
    temporary.replace(path)


def install_dependencies() -> None:
    subprocess.run(
        [
            sys.executable,
            "-m",
            "pip",
            "install",
            "--disable-pip-version-check",
            "--quiet",
            "-r",
            str(ROOT / "requirements-kaggle.txt"),
        ],
        check=True,
    )


def hardware_probe() -> dict[str, Any]:
    import torch

    completed = subprocess.run(
        [
            "nvidia-smi",
            "--query-gpu=index,name,memory.total,compute_cap",
            "--format=csv,noheader,nounits",
        ],
        text=True,
        capture_output=True,
        check=True,
    )
    rows = [line.strip() for line in completed.stdout.splitlines() if line.strip()]
    if torch.cuda.device_count() != 2:
        raise RuntimeError(f"Expected two CUDA devices, found {torch.cuda.device_count()}: {rows}")
    devices = []
    for index in range(2):
        name = torch.cuda.get_device_name(index)
        capability = list(torch.cuda.get_device_capability(index))
        left = torch.ones((64, 64), device=f"cuda:{index}")
        right = torch.full((64, 64), 2.0, device=f"cuda:{index}")
        value = float((left @ right)[0, 0].cpu())
        devices.append(
            {
                "index": index,
                "name": name,
                "capability": capability,
                "matmul_value": value,
                "matmul_ok": value == 128.0,
            }
        )
    if not all("T4" in device["name"] and device["matmul_ok"] for device in devices):
        raise RuntimeError(f"Refusing long campaign on unexpected or broken devices: {devices}")
    return {"nvidia_smi": rows, "torch": torch.__version__, "devices": devices}


def recursively_collect_questions(value: Any, questions: set[str]) -> None:
    if isinstance(value, dict):
        question = value.get("question")
        if isinstance(question, str):
            questions.add(question)
        for child in value.values():
            recursively_collect_questions(child, questions)
    elif isinstance(value, list):
        for child in value:
            recursively_collect_questions(child, questions)


def prepare_inputs(config: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    from datasets import load_dataset
    from huggingface_hub import snapshot_download

    os.environ.setdefault("HF_HUB_DISABLE_IMPLICIT_TOKEN", "1")
    os.environ["HF_HOME"] = "/tmp/cot-drift-hf"
    model_path = snapshot_download(
        repo_id=config["model_id"],
        revision=config["model_revision"],
        cache_dir=os.environ["HF_HOME"],
        token=False,
    )
    dataset = load_dataset(
        config["dataset_id"],
        config["dataset_config"],
        split=config["dataset_split"],
        revision=config["dataset_revision"],
        token=False,
    )
    excluded: set[str] = set()
    for relative in config["prior_artifacts"]:
        artifact = ROOT.joinpath(*relative.split("/"))
        recursively_collect_questions(json.loads(artifact.read_text(encoding="utf-8")), excluded)

    total = sum(
        int(config[key])
        for key in (
            "calibration_examples",
            "search_examples",
            "validation_examples",
            "holdout_examples",
        )
    )
    selected = []
    for row in dataset.shuffle(seed=int(config["problem_seed"])):
        if row["question"] in excluded:
            continue
        answer = row["answer"].split("####")[-1].strip().replace(",", "")
        selected.append({"question": row["question"], "answer": answer})
        if len(selected) == total:
            break
    if len(selected) != total:
        raise RuntimeError(f"Selected {len(selected)} of {total} required fresh problems")

    calibration_end = int(config["calibration_examples"])
    search_end = calibration_end + int(config["search_examples"])
    validation_end = search_end + int(config["validation_examples"])
    payload = {
        "model": {"id": config["model_id"], "revision": config["model_revision"]},
        "dataset": {
            "id": config["dataset_id"],
            "revision": config["dataset_revision"],
            "excluded_prior_questions": len(excluded),
        },
        "splits": {
            "calibration": selected[:calibration_end],
            "search": selected[calibration_end:search_end],
            "validation": selected[search_end:validation_end],
            "holdout": selected[validation_end:],
        },
    }
    atomic_json_write(PROBLEMS_PATH, payload)
    return model_path, payload


def shard_path(family: str) -> Path:
    return WORKING / f"bounded_{family}.json"


def checkpoint_summary(family: str) -> dict[str, Any] | None:
    path = WORKING / f"checkpoint_{family}.json"
    if not path.is_file():
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return {
            key: data.get(key)
            for key in (
                "state",
                "generation",
                "total_generations",
                "best_generation",
                "best_validation_loss",
                "elapsed_seconds",
            )
        }
    except (OSError, json.JSONDecodeError):
        return {"state": "checkpoint_unreadable"}


def launch_workers(config: dict[str, Any], model_path: str) -> dict[str, int]:
    processes: dict[str, subprocess.Popen[Any]] = {}
    logs: dict[str, Any] = {}
    started = time.monotonic()
    try:
        for family in FAMILIES:
            env = os.environ.copy()
            env.update(
                {
                    "CUDA_VISIBLE_DEVICES": str(config["families"][family]["physical_gpu"]),
                    "HF_HUB_OFFLINE": "1",
                    "HF_DATASETS_OFFLINE": "1",
                    "HF_HUB_DISABLE_IMPLICIT_TOKEN": "1",
                    "TOKENIZERS_PARALLELISM": "false",
                    "OMP_NUM_THREADS": "2",
                    "PYTORCH_CUDA_ALLOC_CONF": "expandable_segments:True",
                }
            )
            log_path = WORKING / f"worker_{family}.log"
            logs[family] = log_path.open("w", encoding="utf-8")
            command = [
                sys.executable,
                str(ROOT / "run_bounded_worker.py"),
                "--family",
                family,
                "--config",
                str(CONFIG_PATH),
                "--problems",
                str(PROBLEMS_PATH),
                "--model-path",
                model_path,
                "--output",
                str(shard_path(family)),
            ]
            processes[family] = subprocess.Popen(
                command,
                cwd=str(ROOT),
                env=env,
                stdout=logs[family],
                stderr=subprocess.STDOUT,
            )
        timeout = int(config["worker_timeout_seconds"])
        poll_seconds = int(config["status_poll_seconds"])
        while any(process.poll() is None for process in processes.values()):
            elapsed = time.monotonic() - started
            status = {
                "state": "running",
                "elapsed_seconds": elapsed,
                "workers": {
                    family: {
                        "returncode": process.poll(),
                        "checkpoint": checkpoint_summary(family),
                    }
                    for family, process in processes.items()
                },
            }
            atomic_json_write(STATUS_PATH, status)
            print(json.dumps(status), flush=True)
            if elapsed > timeout:
                for process in processes.values():
                    if process.poll() is None:
                        process.terminate()
                raise TimeoutError(f"Workers exceeded coordinator timeout of {timeout} seconds")
            time.sleep(poll_seconds)
        return {family: int(process.returncode or 0) for family, process in processes.items()}
    finally:
        for log in logs.values():
            log.close()


def load_or_placeholder(family: str, returncode: int | None, error: str | None = None) -> dict[str, Any]:
    path = shard_path(family)
    if path.is_file():
        return json.loads(path.read_text(encoding="utf-8"))
    placeholder = {
        "status": "failed",
        "family": family,
        "returncode": returncode,
        "error": error or "Worker did not produce its result file",
        "checkpoint": checkpoint_summary(family),
    }
    atomic_json_write(path, placeholder)
    return placeholder


def cross_comparison(treatment: dict[str, Any], control: dict[str, Any], seed: int) -> dict[str, Any]:
    from bounded_controller import paired_summary

    treatment_questions = [row["question"] for row in treatment["rows"]]
    control_questions = [row["question"] for row in control["rows"]]
    if treatment_questions != control_questions:
        raise ValueError("Cross-family holdout rows are not aligned")
    deltas = [
        left["loss"] - right["loss"]
        for left, right in zip(treatment["rows"], control["rows"])
    ]
    return paired_summary(deltas, seed)


def aggregate(config: dict[str, Any], hardware: dict[str, Any], shards: dict[str, Any], elapsed: float) -> dict[str, Any]:
    complete = all(shard.get("status") == "complete" for shard in shards.values())
    result: dict[str, Any] = {
        "status": "complete" if complete else "partial",
        "config": config,
        "hardware": hardware,
        "environment": {"python": sys.version, "platform": platform.platform()},
        "elapsed_seconds": elapsed,
        "shards": {},
        "cross_family": {},
    }
    for family, shard in shards.items():
        if shard.get("status") != "complete":
            result["shards"][family] = shard
            continue
        result["shards"][family] = {
            "status": "complete",
            "output_names": shard["output_names"],
            "parameter_count": shard["parameter_count"],
            "selection": shard["selection"],
            "trace_summary": shard["trace_summary"],
            "holdout_mean_losses": {
                name: evaluation["mean_loss"]
                for name, evaluation in shard["holdout"]["evaluations"].items()
            },
            "dynamic_comparisons": shard["holdout"]["dynamic_comparisons"],
            "paired_intervention_audit": {
                "total_effect": shard["paired_intervention_audit"]["total_effect"],
                "isolation_effect": shard["paired_intervention_audit"]["isolation_effect"],
                "relative_drift_threshold": shard["paired_intervention_audit"][
                    "relative_drift_threshold"
                ],
            },
            "elapsed_seconds": shard["elapsed_seconds"],
        }
    if complete:
        simpler = shards["e1_e2_h"]["holdout"]["evaluations"]
        richer = shards["e1_e2_e3_h"]["holdout"]["evaluations"]
        result["cross_family"] = {
            "richer_dynamic_vs_simpler_dynamic": cross_comparison(
                richer["dynamic"], simpler["dynamic"], int(config["problem_seed"]) + 2000
            ),
            "lexical_replay_max_abs_loss_difference": max(
                abs(left["loss"] - right["loss"])
                for left, right in zip(richer["lexical"]["rows"], simpler["lexical"]["rows"])
            ),
        }
        dynamic_losses = {
            family: shard["holdout"]["evaluations"]["dynamic"]["mean_loss"]
            for family, shard in shards.items()
        }
        best_family = min(dynamic_losses, key=dynamic_losses.get)
        best_shard = shards[best_family]
        versus_lexical = best_shard["holdout"]["dynamic_comparisons"]["lexical"]
        audit = best_shard["paired_intervention_audit"]
        result["decision"] = {
            "best_dynamic_family": best_family,
            "dynamic_holdout_losses": dynamic_losses,
            "best_dynamic_operating_regime": {
                "holdout_G_lt_0": versus_lexical["mean_delta_loss_G"] < 0,
                "holdout_W_gt_0_5": versus_lexical["win_rate_W"] > 0.5,
                "audit_total_G_lt_0": audit["total_effect"]["mean_delta_loss_G"] < 0,
                "audit_total_W_gt_0_5": audit["total_effect"]["win_rate_W"] > 0.5,
                "audit_isolation_G_lt_0": audit["isolation_effect"]["mean_delta_loss_G"] < 0,
                "audit_isolation_W_gt_0_5": audit["isolation_effect"]["win_rate_W"] > 0.5,
            },
        }
    return result


def main() -> None:
    WORKING.mkdir(parents=True, exist_ok=True)
    started = time.time()
    config = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    hardware: dict[str, Any] = {}
    returncodes: dict[str, int] = {}
    fatal_error: str | None = None
    try:
        print("[setup] installing pinned dependencies", flush=True)
        install_dependencies()
        hardware = hardware_probe()
        print(json.dumps({"hardware": hardware}, indent=2), flush=True)
        print("[setup] resolving pinned model and fresh problem splits", flush=True)
        model_path, problem_manifest = prepare_inputs(config)
        print(
            json.dumps(
                {
                    "model_path": model_path,
                    "split_sizes": {
                        name: len(rows) for name, rows in problem_manifest["splits"].items()
                    },
                },
                indent=2,
            ),
            flush=True,
        )
        returncodes = launch_workers(config, model_path)
    except Exception as error:
        fatal_error = f"{type(error).__name__}: {error}"
        traceback.print_exc()

    shards = {
