"""Coordinate a paired dual-T4 static e1/norm-matched-h response curve."""

from __future__ import annotations

import json
import os
import platform
import subprocess
import sys
import time
import traceback
from pathlib import Path
from typing import Any


ROOT = Path(__file__).resolve().parent
WORKING = Path("/kaggle/working") if Path("/kaggle/working").is_dir() else ROOT / ".kaggle-working"
CONFIG_PATH = ROOT / "alpha_edge_campaign_config.json"
PROBLEMS_PATH = WORKING / "alpha_edge_problems.json"
RESULT_PATH = WORKING / "alpha_edge_campaign.json"
STATUS_PATH = WORKING / "alpha_edge_status.json"
SHARD_COUNT = 2


def atomic_json_write(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, indent=2) + "\n", encoding="utf-8")
    temporary.replace(path)


def install_dependencies() -> None:
    subprocess.run(
        [
            sys.executable,
            "-m",
            "pip",
            "install",
            "--disable-pip-version-check",
            "--quiet",
            "-r",
            str(ROOT / "requirements-kaggle.txt"),
        ],
        check=True,
    )


def hardware_probe() -> dict[str, Any]:
    import torch

    completed = subprocess.run(
        [
            "nvidia-smi",
            "--query-gpu=index,name,memory.total,compute_cap",
            "--format=csv,noheader,nounits",
        ],
        text=True,
        capture_output=True,
        check=True,
    )
    rows = [line.strip() for line in completed.stdout.splitlines() if line.strip()]
    if torch.cuda.device_count() != SHARD_COUNT:
        raise RuntimeError(f"Expected two CUDA devices, found {torch.cuda.device_count()}: {rows}")
    devices = []
    for index in range(SHARD_COUNT):
        name = torch.cuda.get_device_name(index)
        left = torch.ones((64, 64), device=f"cuda:{index}")
        right = torch.full((64, 64), 2.0, device=f"cuda:{index}")
        value = float((left @ right)[0, 0].cpu())
        devices.append(
            {
                "index": index,
                "name": name,
                "capability": list(torch.cuda.get_device_capability(index)),
                "matmul_value": value,
                "matmul_ok": value == 128.0,
            }
        )
    if not all("T4" in device["name"] and device["matmul_ok"] for device in devices):
        raise RuntimeError(f"Refusing long campaign on unexpected or broken devices: {devices}")
    return {"nvidia_smi": rows, "torch": torch.__version__, "devices": devices}


def recursively_collect_questions(value: Any, questions: set[str]) -> None:
    if isinstance(value, dict):
        question = value.get("question")
        if isinstance(question, str):
            questions.add(question)
        for child in value.values():
            recursively_collect_questions(child, questions)
    elif isinstance(value, list):
        for child in value:
            recursively_collect_questions(child, questions)


def replay_prior_campaigns(dataset: Any, config: dict[str, Any], excluded: set[str]) -> list[dict[str, Any]]:
    records = []
    for replay in config.get("prior_campaign_replays", []):
        seed = int(replay["problem_seed"])
        required = int(replay["examples"])
        selected = []
        for row in dataset.shuffle(seed=seed):
            if row["question"] in excluded:
                continue
            selected.append(row["question"])
            if len(selected) == required:
                break
        if len(selected) != required:
            raise RuntimeError(f"Replayed {len(selected)} of {required} problems for seed {seed}")
        excluded.update(selected)
        records.append(
            {
                "problem_seed": seed,
                "examples": required,
                "first_question": selected[0],
                "last_question": selected[-1],
            }
        )
    return records


def prepare_inputs(config: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    from datasets import load_dataset
    from huggingface_hub import snapshot_download

    os.environ.setdefault("HF_HUB_DISABLE_IMPLICIT_TOKEN", "1")
    os.environ["HF_HOME"] = "/tmp/cot-drift-hf"
    model_path = snapshot_download(
        repo_id=config["model_id"],
        revision=config["model_revision"],
        cache_dir=os.environ["HF_HOME"],
        token=False,
    )
    dataset = load_dataset(
        config["dataset_id"],
        config["dataset_config"],
        split=config["dataset_split"],
        revision=config["dataset_revision"],
        token=False,
    )
    excluded: set[str] = set()
    for relative in config["prior_artifacts"]:
        artifact = ROOT.joinpath(*relative.split("/"))
        recursively_collect_questions(json.loads(artifact.read_text(encoding="utf-8")), excluded)
    artifact_exclusion_count = len(excluded)
    replay_records = replay_prior_campaigns(dataset, config, excluded)

    selection_count = int(config["selection_examples"])
    test_count = int(config["test_examples"])
    required = selection_count + test_count
    selected = []
    for row in dataset.shuffle(seed=int(config["problem_seed"])):
        if row["question"] in excluded:
            continue
        answer = row["answer"].split("####")[-1].strip().replace(",", "")
        selected.append(
            {
                "problem_index": len(selected),
                "question": row["question"],
                "answer": answer,
            }
        )
        if len(selected) == required:
            break
    if len(selected) != required:
        raise RuntimeError(f"Selected {len(selected)} of {required} required fresh problems")

    payload = {
        "model": {"id": config["model_id"], "revision": config["model_revision"]},
        "dataset": {
            "id": config["dataset_id"],
            "revision": config["dataset_revision"],
            "artifact_exclusion_count": artifact_exclusion_count,
            "total_excluded_prior_questions": len(excluded),
            "prior_campaign_replays": replay_records,
        },
        "splits": {
            "selection": selected[:selection_count],
            "test": selected[selection_count:],
        },
    }
    atomic_json_write(PROBLEMS_PATH, payload)
    return model_path, payload


def shard_path(shard_id: int) -> Path:
    return WORKING / f"alpha_edge_shard_{shard_id}.json"


def checkpoint_summary(shard_id: int) -> dict[str, Any] | None:
    path = WORKING / f"checkpoint_alpha_edge_shard_{shard_id}.json"
    if not path.is_file():
        return None
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
        return {
            key: value.get(key)
            for key in (
                "state",
                "split",
                "completed_examples",
                "total_examples",
                "elapsed_seconds",
            )
        }
    except (OSError, json.JSONDecodeError):
        return {"state": "checkpoint_unreadable"}


def launch_workers(config: dict[str, Any], model_path: str) -> dict[int, int]:
    processes: dict[int, subprocess.Popen[Any]] = {}
    logs: dict[int, Any] = {}
    started = time.monotonic()
    try:
        for shard_id in range(SHARD_COUNT):
            env = os.environ.copy()
            env.update(
                {
                    "CUDA_VISIBLE_DEVICES": str(shard_id),
                    "HF_HUB_OFFLINE": "1",
                    "HF_DATASETS_OFFLINE": "1",
                    "HF_HUB_DISABLE_IMPLICIT_TOKEN": "1",
                    "TOKENIZERS_PARALLELISM": "false",
                    "OMP_NUM_THREADS": "2",
                    "PYTORCH_CUDA_ALLOC_CONF": "expandable_segments:True",
                }
            )
            log_path = WORKING / f"worker_alpha_edge_shard_{shard_id}.log"
            logs[shard_id] = log_path.open("w", encoding="utf-8")
            command = [
                sys.executable,
                str(ROOT / "run_alpha_edge_worker.py"),
                "--shard-id",
                str(shard_id),
                "--shard-count",
                str(SHARD_COUNT),
                "--config",
                str(CONFIG_PATH),
                "--problems",
                str(PROBLEMS_PATH),
                "--model-path",
                model_path,
                "--output",
                str(shard_path(shard_id)),
            ]
            processes[shard_id] = subprocess.Popen(
                command,
                cwd=str(ROOT),
                env=env,
                stdout=logs[shard_id],
                stderr=subprocess.STDOUT,
            )

        timeout = int(config["worker_timeout_seconds"])
        poll_seconds = int(config["status_poll_seconds"])
        while any(process.poll() is None for process in processes.values()):
            elapsed = time.monotonic() - started
            status = {
                "state": "running",
                "elapsed_seconds": elapsed,
                "workers": {
                    str(shard_id): {
                        "returncode": process.poll(),
                        "checkpoint": checkpoint_summary(shard_id),
                    }
                    for shard_id, process in processes.items()
                },
            }
            atomic_json_write(STATUS_PATH, status)
            print(json.dumps(status), flush=True)
            if elapsed > timeout:
                for process in processes.values():
                    if process.poll() is None:
                        process.terminate()
                raise TimeoutError(f"Workers exceeded coordinator timeout of {timeout} seconds")
            time.sleep(poll_seconds)
        return {shard_id: int(process.returncode or 0) for shard_id, process in processes.items()}
    finally:
        for log in logs.values():
            log.close()


def load_or_placeholder(shard_id: int, returncode: int | None, error: str | None) -> dict[str, Any]:
    path = shard_path(shard_id)
    if path.is_file():
        return json.loads(path.read_text(encoding="utf-8"))
    placeholder = {
        "status": "failed",
        "shard_id": shard_id,
        "returncode": returncode,
        "error": error or "Worker did not produce its result file",
        "checkpoint": checkpoint_summary(shard_id),
    }
    atomic_json_write(path, placeholder)
    return placeholder


def merge_split(
    shards: dict[int, dict[str, Any]], split_name: str, config: dict[str, Any]
) -> dict[str, Any]:
    from alpha_edge import (
        alpha_key,
        paired_exact_match_summary,
        paired_loss_summary,
        summarize_geometry,
    )

    alpha_keys = [alpha_key(value) for value in config["alphas"]]
    expected = int(config[f"{split_name}_examples"])
    evaluations: dict[str, Any] = {}
    geometry: dict[str, Any] = {}
    for alpha_index, key in enumerate(alpha_keys):
        rows = [
            row
            for shard in shards.values()
            for row in shard["splits"][split_name]["evaluations"][key]["rows"]
        ]
        rows.sort(key=lambda row: int(row["problem_index"]))
        indices = [int(row["problem_index"]) for row in rows]
        if len(rows) != expected or len(set(indices)) != expected:
            raise ValueError(
                f"Split {split_name} alpha {key} has {len(rows)} rows and "
                f"{len(set(indices))} unique indices; expected {expected}"
            )
        evaluations[key] = {
            "alpha": float(key),
            "count": len(rows),
            "mean_loss": sum(float(row["loss"]) for row in rows) / len(rows),
            "exact_match": sum(bool(row["correct"]) for row in rows) / len(rows),
            "rows": rows,
        }
        if split_name == "selection":
            raw_values = [
                value
                for shard in shards.values()
                for value in shard["splits"][split_name]["geometry_samples"][key][
                    "raw_h_over_e1"
                ]
            ]
            relative_values = [
                value
                for shard in shards.values()
                for value in shard["splits"][split_name]["geometry_samples"][key][
                    "relative_drift"
                ]
            ]
            geometry[key] = {
                "raw_h_over_e1": summarize_geometry(raw_values),
                "relative_drift": summarize_geometry(relative_values),
            }

    lexical_rows = evaluations[alpha_keys[0]]["rows"]
    comparisons = {}
    for alpha_index, key in enumerate(alpha_keys):
        comparisons[key] = {
            "alpha": float(key),
            "loss": paired_loss_summary(
                evaluations[key]["rows"],
                lexical_rows,
                seed=int(config["problem_seed"]) + 100 * (split_name == "test") + alpha_index,
                trim_fraction=float(config["trim_fraction"]),
            ),
            "exact_match": paired_exact_match_summary(
                evaluations[key]["rows"],
                lexical_rows,
                seed=int(config["problem_seed"]) + 500 + 100 * (split_name == "test") + alpha_index,
            ),
        }
    return {"evaluations": evaluations, "comparisons_vs_lexical": comparisons, "geometry": geometry}


def aggregate(
    config: dict[str, Any],
    hardware: dict[str, Any],
    problem_manifest: dict[str, Any] | None,
    shards: dict[int, dict[str, Any]],
    elapsed: float,
) -> dict[str, Any]:
    from alpha_edge import alpha_key

    complete = all(shard.get("status") == "complete" for shard in shards.values())
    result: dict[str, Any] = {
        "status": "complete" if complete else "partial",
        "config": config,
        "hardware": hardware,
        "problem_manifest": problem_manifest,
        "environment": {"python": sys.version, "platform": platform.platform()},
        "elapsed_seconds": elapsed,
        "shards": {
            str(shard_id): {
                key: shard.get(key)
                for key in ("status", "shard_id", "fingerprint", "environment", "elapsed_seconds", "error")
                if key in shard
            }
            for shard_id, shard in shards.items()
        },
    }
    if not complete:
        return result

    selection = merge_split(shards, "selection", config)
    test = merge_split(shards, "test", config)
    alpha_keys = [alpha_key(value) for value in config["alphas"]]
    selected_key = min(
        alpha_keys,
        key=lambda key: (selection["evaluations"][key]["mean_loss"], float(key)),
    )
    selected_comparison = test["comparisons_vs_lexical"][selected_key]
    selected_alpha = float(selected_key)
    result.update(
        {
            "selection": selection,
            "test": test,
            "decision": {
                "criterion": "lowest selection mean answer-token NLL; smaller alpha breaks exact ties",
                "selected_alpha": selected_alpha,
                "selection_loss": selection["evaluations"][selected_key]["mean_loss"],
                "test_loss": test["evaluations"][selected_key]["mean_loss"],
                "lexical_test_loss": test["evaluations"][alpha_keys[0]]["mean_loss"],
                "selected_test_comparison": selected_comparison,
                "selected_alpha_is_interior": 0.0 < selected_alpha < max(config["alphas"]),
                "test_curve_min_alpha_descriptive_only": float(
                    min(
                        alpha_keys,
                        key=lambda key: (test["evaluations"][key]["mean_loss"], float(key)),
                    )
                ),
                "loss_ci_supports_selected_below_lexical": selected_comparison["loss"][
                    "mean_delta_bootstrap_95"
                ][1]
                < 0.0,
                "win_ci_supports_selected_above_half": selected_comparison["loss"][
                    "win_rate_wilson_95"
                ][0]
                > 0.5,
                "alpha_0_20_turns_up_from_selected_on_test": test["evaluations"][
                    alpha_key(max(config["alphas"]))
                ]["mean_loss"]
                > test["evaluations"][selected_key]["mean_loss"],
            },
        }
    )
    return result


def main() -> None:
    WORKING.mkdir(parents=True, exist_ok=True)
    started = time.time()
    config = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    hardware: dict[str, Any] = {}
    returncodes: dict[int, int] = {}
    problem_manifest: dict[str, Any] | None = None
    fatal_error: str | None = None
    try:
        print("[setup] installing pinned dependencies", flush=True)
        install_dependencies()
        hardware = hardware_probe()
        print(json.dumps({"hardware": hardware}, indent=2), flush=True)
        print("[setup] resolving pinned model and fresh problem splits", flush=True)
        model_path, problem_manifest = prepare_inputs(config)
        print(
            json.dumps(
                {
                    "model_path": model_path,
                    "split_sizes": {
                        name: len(rows) for name, rows in problem_manifest["splits"].items()
                    },
                    "dataset": problem_manifest["dataset"],
                },
                indent=2,
            ),
            flush=True,
        )
        returncodes = launch_workers(config, model_path)
    except Exception as error:
        fatal_error = f"{type(error).__name__}: {error}"
        traceback.print_exc()

    shards = {
        shard_id: load_or_placeholder(shard_id, returncodes.get(shard_id), fatal_error)
        for shard_id in range(SHARD_COUNT)
    }
    try:
        result = aggregate(
            config, hardware, problem_manifest, shards, time.time() - started
        )
    except Exception as error:
        if fatal_error is None:
            fatal_error = f"{type(error).__name__}: {error}"
        traceback.print_exc()
        result = {
            "status": "failed",
            "config": config,
            "hardware": hardware,
            "problem_manifest": problem_manifest,
            "shards": shards,
            "elapsed_seconds": time.time() - started,
        }
    if fatal_error:
        result["coordinator_error"] = fatal_error
    atomic_json_write(RESULT_PATH, result)
    atomic_json_write(
        STATUS_PATH,
        {
            "state": result["status"],
            "result": str(RESULT_PATH),
            "worker_returncodes": {str(key): value for key, value in returncodes.items()},
            "coordinator_error": fatal_error,
            "elapsed_seconds": result["elapsed_seconds"],
        },
    )
    print(json.dumps(result, indent=2), flush=True)


if __name__ == "__main__":
    main()

